CustomField.formula:
ROUND( 9 * (

   ( 5 * FLOOR( ( DATEVALUE(  CompletedDateTime ) - DATE( 1900, 1, 8) ) / 7) +

    MIN(5, 

     MOD( DATEVALUE( CompletedDateTime ) - DATE( 1900, 1, 8), 7) +

     MIN( 1, 24 / 9 * ( MOD( CompletedDateTime - DATETIMEVALUE( '1900-01-08 09:00:00' ), 1 ) ) )

    ) 

   )

 -

   ( 5 * FLOOR( ( DATEVALUE(   Create_Date_Time__c     ) - DATE( 1900, 1, 8) ) / 7) +

     MIN( 5,

      MOD( DATEVALUE( Create_Date_Time__c ) - DATE( 1996, 1, 1), 7 ) +

      MIN( 1, 24 / 9 * ( MOD( Create_Date_Time__c - DATETIMEVALUE( '1900-01-08 09:00:00' ), 1) ) )

    )

   ) 

  ), 

0 )
